package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class CampaignService {
 public record Input(@NotBlank @Size(max=200) String name,@Size(max=4000) String description,@NotNull UUID ownerMemberId,@NotNull @Pattern(regexp="FOLLOW_UP|EMAIL_DRAFT") String channel,@Min(0) @Max(100000000000L) long budgetCents,@NotBlank @Size(max=200) String subject,@NotBlank @Size(max=4000) String body,@NotNull LocalDate taskDueDate,@Min(0) long expectedVersion){}
 public record MemberInput(@NotNull @Pattern(regexp="CONTACT|LEAD") String type,@NotNull UUID subjectId,@Min(0) long expectedVersion){}
 public record ConsentInput(@NotNull @Pattern(regexp="CONTACT|LEAD") String type,@NotNull UUID subjectId,@NotNull @Pattern(regexp="FOLLOW_UP|EMAIL_DRAFT") String channel,@NotNull @Pattern(regexp="OPT_IN|OPT_OUT") String state,@NotBlank @Size(max=200) String source,@NotBlank @Size(max=1000) String evidence,@Min(0) long expectedVersion){}
 public record Decision(@Min(0) long expectedVersion,Instant scheduledAt,@Size(max=1000) String reason){}
 public record ResultInput(@Min(0) long expectedVersion,@NotNull @Pattern(regexp="CONTACTED|RESPONDED|CONVERTED|NO_RESPONSE|OPT_OUT") String outcome,@Min(0) @Max(100000000000L) long costCents,@Size(max=2000) String notes){}
 private final P3Base b;public CampaignService(P3Base b){this.b=b;}
 private static final String FROM=" FROM crm_campaign x JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.owner_member_id ";
 private static final String READ="x.tenant_id=:tenant AND :campaignReader AND "+P3Base.own("campaign","x","m",false);
 private static final String SELECT="SELECT x.*,m.display_name AS owner_name,(:campaignWriter AND "+P3Base.own("campaign","x","m",true)+") AS can_manage"+FROM;
 Map<String,Object> campaign(AuthService.Actor a,UUID id){var p=b.params(a);p.put("id",id);var r=b.one(SELECT+" WHERE "+READ+" AND x.id=:id",p);r.put("canWrite",Boolean.TRUE.equals(r.get("canManage"))&&Set.of("DRAFT","BLOCKED").contains(r.get("status")));r.put("canLaunch",Boolean.TRUE.equals(r.get("canManage"))&&a.p3Access().campaignLaunch());return r;}
 private Map<String,Object> subject(AuthService.Actor a,String type,UUID id,boolean write){if(type.equals("CONTACT")){if(!a.businessAccess().contactRead())throw ApiError.forbidden("没有联系人读取权限");var c=b.business.contact(a,id);if(write&&!c.canWrite())throw ApiError.forbidden("没有联系人的营销写入权限");return map("id",id,"type",type,"name",c.name(),"company",c.customerName(),"email",c.email(),"customerId",c.customerId(),"ownerMemberId",b.customers.get(a,c.customerId()).ownerMemberId());}if(!a.businessAccess().leads().read())throw ApiError.forbidden("没有线索读取权限");var l=b.business.lead(a,id);if(write&&!l.canWrite())throw ApiError.forbidden("线索已转换或没有营销写入权限");return map("id",id,"type",type,"name",l.name(),"company",l.companyName(),"email",l.email(),"customerId",null,"ownerMemberId",l.ownerMemberId());}
 private Map<String,Object> consent(AuthService.Actor a,String type,UUID id,String channel){var rs=b.rows("SELECT * FROM crm_marketing_consent WHERE tenant_id=:tenant AND "+(type.equals("CONTACT")?"contact_id":"lead_id")+"=:id AND channel=:channel",map("tenant",a.tenant().id(),"id",id,"channel",channel));return rs.isEmpty()?map("state","UNKNOWN","version",0):rs.getFirst();}
 public Object consent(AuthService.Session s,ConsentInput i,UUID trace){return b.scoped(s,"campaign",true,a->{subject(a,i.type(),i.subjectId(),true);var old=consent(a,i.type(),i.subjectId(),i.channel());if(old.containsKey("id")){b.version(old,i.expectedVersion());b.db.update("UPDATE crm_marketing_consent SET state=:state,source=:source,evidence=:evidence,actor_member_id=:member,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",old.get("id"),"state",i.state(),"source",text(i.source()),"evidence",text(i.evidence()),"member",a.tenant().memberId()));}else{if(i.expectedVersion()!=0)throw ApiError.conflict("许可状态已变化");b.db.update("INSERT INTO crm_marketing_consent(id,tenant_id,contact_id,lead_id,channel,state,source,evidence,actor_member_id) VALUES(:id,:tenant,:contact,:lead,:channel,:state,:source,:evidence,:member)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"contact",i.type().equals("CONTACT")?i.subjectId():null,"lead",i.type().equals("LEAD")?i.subjectId():null,"channel",i.channel(),"state",i.state(),"source",text(i.source()),"evidence",text(i.evidence()),"member",a.tenant().memberId()));}var current=consent(a,i.type(),i.subjectId(),i.channel());b.audit(a,"MARKETING_CONSENT_CHANGED","MARKETING_CONSENT",(UUID)current.get("id"),number(current,"version"),trace);return current;});}
 public Object getConsent(AuthService.Session s,String type,UUID id,String channel){if(!Set.of("CONTACT","LEAD").contains(type)||!Set.of("FOLLOW_UP","EMAIL_DRAFT").contains(channel))throw ApiError.bad("目标或渠道无效");return b.scoped(s,"campaign",false,a->{subject(a,type,id,false);return consent(a,type,id,channel);});}
 public Object subjects(AuthService.Session s,String type,int page,int size,String q){page(page,size,q);if(!Set.of("CONTACT","LEAD").contains(type))throw ApiError.bad("目标类型无效");return b.scoped(s,"campaign",false,a->{var rs=type.equals("CONTACT")?b.business.contacts(s,page,size,q,null):b.business.leads(s,page,size,q,"");return rs;});}
 public Object list(AuthService.Session s,int page,int size,String q,String state){page(page,size,q);if(!Set.of("","DRAFT","SCHEDULED","RUNNING","COMPLETED","CANCELLED","BLOCKED").contains(state))throw ApiError.bad("活动状态无效");return b.scoped(s,"campaign",false,a->{var p=b.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"state",state,"limit",size,"offset",((long)page-1)*size));String where=READ+" AND(:state='' OR x.status=:state) AND(:q='' OR strpos(lower(x.name),:q)>0)";return new BusinessService.Page<>(b.rows(SELECT+" WHERE "+where+" ORDER BY x.updated_at DESC,x.id LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*)"+FROM+" WHERE "+where,p,Long.class));});}
 public Object get(AuthService.Session s,UUID id){return b.scoped(s,"campaign",false,a->campaign(a,id));}
 public Object owners(AuthService.Session s){return b.scoped(s,"campaign",false,a->b.memberOptions(a,"campaign"));}
 public Object save(AuthService.Session s,UUID id,Input i,String key,UUID trace){date(i.taskDueDate());template(i.subject());template(i.body());return b.scoped(s,"campaign",true,a->{if(b.memberOptions(a,"campaign").stream().noneMatch(m->i.ownerMemberId().equals(m.get("id"))))throw ApiError.bad("活动负责人不在可分配范围");UUID selected=id==null?b.once(a,"campaign.create",key,i,()->{UUID created=UUID.randomUUID();b.db.update("INSERT INTO crm_campaign(id,tenant_id,name,description,owner_member_id,channel,budget_cents,subject,body,task_due_date) VALUES(:id,:tenant,:name,:description,:owner,:channel,:budget,:subject,:body,:date)",input(a,created,i));revision(a,created,"CREATED","",trace);return created;}):id;if(id!=null){var old=campaign(a,id);if(!Boolean.TRUE.equals(old.get("canWrite")))throw ApiError.forbidden("仅活动草稿 / 待修正可编辑");b.version(old,i.expectedVersion());if(!old.get("channel").equals(i.channel())&&b.db.queryForObject("SELECT count(*) FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:id AND status='ACTIVE'",map("tenant",a.tenant().id(),"id",id),Integer.class)>0)throw ApiError.conflict("已有目标时不能切换渠道");b.db.update("UPDATE crm_campaign SET name=:name,description=:description,owner_member_id=:owner,channel=:channel,budget_cents=:budget,subject=:subject,body=:body,task_due_date=:date,status='DRAFT',version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",input(a,id,i));revision(a,id,"UPDATED","",trace);}return campaign(a,selected);});}
 private Map<String,Object> input(AuthService.Actor a,UUID id,Input i){return map("tenant",a.tenant().id(),"id",id,"name",text(i.name()),"description",text(i.description()),"owner",i.ownerMemberId(),"channel",i.channel(),"budget",i.budgetCents(),"subject",text(i.subject()),"body",text(i.body()),"date",i.taskDueDate(),"version",i.expectedVersion());}
 static void template(String value){String s=text(value).replace("{{name}}","").replace("{{company}}","");if(s.contains("{{")||s.contains("}}"))throw ApiError.bad("模板仅支持 {{name}} 与 {{company}} 变量");}
 private List<Map<String,Object>> members(AuthService.Actor a,UUID id,boolean write){var k=campaign(a,id);var rs=b.rows("SELECT * FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:id AND status='ACTIVE' ORDER BY created_at,id",map("tenant",a.tenant().id(),"id",id));var result=new ArrayList<Map<String,Object>>();for(var r:rs){String type=r.get("contactId")!=null?"CONTACT":"LEAD";UUID subjectId=(UUID)(type.equals("CONTACT")?r.get("contactId"):r.get("leadId"));try{var v=subject(a,type,subjectId,write);r.put("subject",v);r.put("consent",consent(a,type,subjectId,(String)k.get("channel")));var ex=b.rows("SELECT * FROM crm_campaign_execution WHERE tenant_id=:tenant AND member_id=:id",map("tenant",a.tenant().id(),"id",r.get("id")));if(!ex.isEmpty()){var execution=ex.getFirst();if(execution.get("taskId")!=null)try{b.sales.task(a,(UUID)execution.get("taskId"));}catch(ApiError denied){execution.put("taskId",null);}r.put("execution",execution);}result.add(r);}catch(ApiError denied){if(write)throw denied;}}return result;}
 public Object members(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return b.scoped(s,"campaign",false,a->{var rows=members(a,id,false);long offset=((long)page-1)*size;return new BusinessService.Page<>(rows.subList((int)Math.min(offset,rows.size()),(int)Math.min(offset+size,rows.size())),page,size,rows.size());});}
 public Object enrol(AuthService.Session s,UUID id,MemberInput i,String key,UUID trace){return b.scoped(s,"campaign",true,a->{UUID selected=b.once(a,"campaign.member",key,map("id",id,"input",i),()->{var k=campaign(a,id);if(!Boolean.TRUE.equals(k.get("canWrite")))throw ApiError.forbidden("先修改草稿活动");b.version(k,i.expectedVersion());subject(a,i.type(),i.subjectId(),true);if(b.db.queryForObject("SELECT count(*) FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:id AND status='ACTIVE'",map("tenant",a.tenant().id(),"id",id),Integer.class)>=500)throw ApiError.bad("每个活动最多500个目标");b.db.update("INSERT INTO crm_campaign_member(id,tenant_id,campaign_id,contact_id,lead_id) VALUES(:memberId,:tenant,:campaign,:contact,:lead)",map("memberId",UUID.randomUUID(),"tenant",a.tenant().id(),"campaign",id,"contact",i.type().equals("CONTACT")?i.subjectId():null,"lead",i.type().equals("LEAD")?i.subjectId():null));b.db.update("UPDATE crm_campaign SET version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));revision(a,id,"TARGET_ADDED","",trace);return id;});return campaign(a,selected);});}
 public Object remove(AuthService.Session s,UUID id,UUID member,Decision i,UUID trace){return b.scoped(s,"campaign",true,a->{var k=campaign(a,id);if(!Boolean.TRUE.equals(k.get("canWrite")))throw ApiError.forbidden("仅草稿可移除目标");b.version(k,i.expectedVersion());var row=b.one("SELECT * FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:id AND id=:member AND status='ACTIVE'",map("tenant",a.tenant().id(),"id",id,"member",member));subject(a,row.get("contactId")!=null?"CONTACT":"LEAD",(UUID)(row.get("contactId")!=null?row.get("contactId"):row.get("leadId")),true);b.db.update("UPDATE crm_campaign_member SET status='REMOVED',version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",member));b.db.update("UPDATE crm_campaign SET version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));revision(a,id,"TARGET_REMOVED",text(i.reason()),trace);return campaign(a,id);});}
 private List<Map<String,Object>> eligible(AuthService.Actor a,UUID id){var k=campaign(a,id);var rows=members(a,id,true);long all=b.db.queryForObject("SELECT count(*) FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:id AND status='ACTIVE'",map("tenant",a.tenant().id(),"id",id),Long.class);if(rows.isEmpty()||rows.size()!=all)throw ApiError.bad("活动需有效目标，且当前可访问全部目标");for(var r:rows){var consent=(Map<?,?>)r.get("consent");if(!"OPT_IN".equals(consent.get("state")))throw ApiError.conflict("先记录全部目标对本渠道的许可，退订目标不可执行");var sub=(Map<?,?>)r.get("subject");if("EMAIL_DRAFT".equals(k.get("channel"))&&(!(sub.get("email") instanceof String email)||email.isBlank()))throw ApiError.bad("邮件草稿目标需要有效邮箱");}if("FOLLOW_UP".equals(k.get("channel"))&&!a.businessAccess().tasks().write())throw ApiError.forbidden("生成跟进任务需要待办写入权限");return rows;}
 public Object preview(AuthService.Session s,UUID id){return b.scoped(s,"campaign",false,a->{var k=campaign(a,id);if(!Boolean.TRUE.equals(k.get("canManage")))throw ApiError.forbidden("执行预览需要活动写入范围");var rows=eligible(a,id);return map("targets",rows.size(),"channel",k.get("channel"),"subject",k.get("subject"),"body",k.get("body"),"externalMailSent",false,"canLaunch",a.p3Access().campaignLaunch());});}
 private void execute(AuthService.Actor a,UUID id,UUID trace){var k=campaign(a,id);var rows=eligible(a,id);for(var r:rows){var sub=(Map<String,Object>)r.get("subject");String title=expand((String)k.get("subject"),sub),body=expand((String)k.get("body"),sub);if(title.length()>200||body.length()>4000)throw ApiError.bad("替换变量后内容超过长度上限");UUID task=null;if("FOLLOW_UP".equals(k.get("channel"))){var input=new SalesService.TaskCreate((UUID)sub.get("customerId"),null,title,body,(UUID)sub.get("ownerMemberId"),java.time.LocalDate.parse(String.valueOf(k.get("taskDueDate"))),"NORMAL");task=(UUID)b.sales.createTask(a.session(),input,"campaign:"+id+":"+r.get("id"),trace).get("id");}b.db.update("INSERT INTO crm_campaign_execution(id,tenant_id,campaign_id,member_id,execution_version,kind,task_id,draft_subject,draft_body) VALUES(:id,:tenant,:campaign,:member,:version,:kind,:task,:subject,:body)",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"campaign",id,"member",r.get("id"),"version",k.get("version"),"kind",k.get("channel"),"task",task,"subject",task==null?title:null,"body",task==null?body:null));}}
 static String expand(String template,Map<String,Object> s){return template.replace("{{name}}",String.valueOf(s.get("name"))).replace("{{company}}",String.valueOf(s.get("company")));}
 public Object action(AuthService.Session s,UUID id,String action,Decision i,String key,UUID trace){return b.scoped(s,Set.of("launch","schedule","complete").contains(action)?"launch":"campaign",true,a->{UUID selected=b.once(a,"campaign."+action,key,map("id",id,"input",i),()->{var k=campaign(a,id);if(!Boolean.TRUE.equals(k.get("canManage")))throw ApiError.forbidden("没有活动写入范围");b.version(k,i.expectedVersion());String state=(String)k.get("status"),next;switch(action){case "launch"->{if(!Set.of("DRAFT","SCHEDULED","BLOCKED").contains(state))throw ApiError.conflict("活动已经执行或取消");execute(a,id,trace);next="RUNNING";}case "schedule"->{if(!Set.of("DRAFT","BLOCKED").contains(state))throw ApiError.conflict("只有草稿可排期");eligible(a,id);if(i.scheduledAt()==null||i.scheduledAt().isBefore(Instant.now().plusSeconds(60))||i.scheduledAt().isAfter(Instant.now().plusSeconds(365L*86400)))throw ApiError.bad("排期需在一分钟后至一年内");next="SCHEDULED";}case "cancel"->{if(!Set.of("DRAFT","SCHEDULED","BLOCKED").contains(state)||text(i.reason()).isEmpty())throw ApiError.bad("仅未执行活动可取消，且需原因");next="CANCELLED";}case "complete"->{if(!state.equals("RUNNING")||text(i.reason()).isEmpty())throw ApiError.bad("仅执行中活动可完成，且需说明");next="COMPLETED";}default->throw ApiError.bad("活动动作无效");}long authVersion=b.db.queryForObject("SELECT auth_version FROM iam_user WHERE id=:id",map("id",a.session().userId()),Long.class);b.db.update("UPDATE crm_campaign SET status=:status,scheduled_at=:scheduled,launch_by_member_id=:member,launch_auth_version=:authVersion,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"status",next,"scheduled",action.equals("schedule")?i.scheduledAt():null,"member",a.tenant().memberId(),"authVersion",authVersion));revision(a,id,action.toUpperCase(Locale.ROOT),text(i.reason()),trace);return id;});return campaign(a,selected);});}
 private void revision(AuthService.Actor a,UUID id,String action,String reason,UUID trace){var k=campaign(a,id);k.remove("canManage");k.remove("canWrite");k.remove("canLaunch");b.db.update("INSERT INTO crm_campaign_revision(id,tenant_id,campaign_id,business_version,action,snapshot,reason,actor_member_id,actor_name_snapshot) VALUES(:revision,:tenant,:campaign,:version,:action,cast(:snapshot AS jsonb),:reason,:member,:name)",map("revision",UUID.randomUUID(),"tenant",a.tenant().id(),"campaign",id,"version",k.get("version"),"action",action,"snapshot",b.json(k),"reason",reason,"member",a.tenant().memberId(),"name",a.tenant().memberName()));b.audit(a,"CAMPAIGN_"+action,"CAMPAIGN",id,number(k,"version"),trace);}
 public Object result(AuthService.Session s,UUID id,UUID member,ResultInput i,String key,UUID trace){return b.scoped(s,"campaign",true,a->{UUID selected=b.once(a,"campaign.result",key,map("id",id,"member",member,"input",i),()->{var k=campaign(a,id);if(!Boolean.TRUE.equals(k.get("canManage"))||!Set.of("RUNNING","COMPLETED").contains(k.get("status")))throw ApiError.forbidden("需在可管理的已执行活动记录结果");var r=b.one("SELECT * FROM crm_campaign_member WHERE tenant_id=:tenant AND campaign_id=:campaign AND id=:id AND status='ACTIVE'",map("tenant",a.tenant().id(),"campaign",id,"id",member));b.version(r,i.expectedVersion());String type=r.get("contactId")!=null?"CONTACT":"LEAD";UUID sub=(UUID)(type.equals("CONTACT")?r.get("contactId"):r.get("leadId"));subject(a,type,sub,true);long spent=b.db.queryForObject("SELECT coalesce(sum(cost_cents),0)::bigint FROM crm_campaign_result WHERE tenant_id=:tenant AND campaign_id=:id",map("tenant",a.tenant().id(),"id",id),Long.class);if(i.costCents()>number(k,"budgetCents")-spent)throw ApiError.conflict("记录费用超过活动剩余预算");UUID created=UUID.randomUUID();b.db.update("INSERT INTO crm_campaign_result(id,tenant_id,campaign_id,member_id,outcome,cost_cents,notes,actor_member_id) VALUES(:id,:tenant,:campaign,:member,:outcome,:cost,:notes,:actor)",map("id",created,"tenant",a.tenant().id(),"campaign",id,"member",member,"outcome",i.outcome(),"cost",i.costCents(),"notes",text(i.notes()),"actor",a.tenant().memberId()));b.db.update("UPDATE crm_campaign_member SET version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",member));if(i.outcome().equals("OPT_OUT")){var current=consent(a,type,sub,(String)k.get("channel"));consent(a.session(),new ConsentInput(type,sub,(String)k.get("channel"),"OPT_OUT","活动结果退订",text(i.notes()).isEmpty()?"活动结果标记为退订":text(i.notes()),number(current,"version")),trace);}b.audit(a,"CAMPAIGN_RESULT_RECORDED","CAMPAIGN_RESULT",created,0,trace);return id;});return report(a,selected);});}
 private Object report(AuthService.Actor a,UUID id){var k=campaign(a,id);var members=members(a,id,false);var totals=new TreeMap<String,Long>();long cost=0;var results=new ArrayList<Map<String,Object>>();for(var r:members){var rs=b.rows("SELECT * FROM crm_campaign_result WHERE tenant_id=:tenant AND member_id=:id ORDER BY created_at DESC,id DESC",map("tenant",a.tenant().id(),"id",r.get("id")));for(var v:rs){cost+=number(v,"costCents");v.put("subject",r.get("subject"));results.add(v);}if(!rs.isEmpty())totals.merge((String)rs.getFirst().get("outcome"),1L,Long::sum);}return map("campaign",k,"visibleTargets",members.size(),"visibleCostCents",cost,"latestOutcomes",totals,"results",results,"externalMailSent",false);}
 public Object report(AuthService.Session s,UUID id){return b.scoped(s,"campaign",false,a->report(a,id));}
 public Object history(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return b.scoped(s,"campaign",false,a->{campaign(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(b.rows("SELECT id,business_version,action,reason,actor_name_snapshot,created_at FROM crm_campaign_revision WHERE tenant_id=:tenant AND campaign_id=:id ORDER BY business_version DESC LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*) FROM crm_campaign_revision WHERE tenant_id=:tenant AND campaign_id=:id",p,Long.class));});}
 public Object version(AuthService.Session s,UUID id,long version){if(version<0)throw ApiError.bad("版本无效");return b.scoped(s,"campaign",false,a->{campaign(a,id);return b.object(String.valueOf(b.one("SELECT snapshot::text AS value FROM crm_campaign_revision WHERE tenant_id=:tenant AND campaign_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version)).get("value")));});}
 public Object run(AuthService.Session s){UUID tenant=b.scoped(s,"launch",true,a->a.tenant().id());return map("processed",scheduled(tenant));}
 int scheduled(UUID tenant){var due=b.tx.execute(st->{b.context(tenant);return b.rows("SELECT x.id,x.launch_by_member_id,x.launch_auth_version FROM crm_campaign x WHERE tenant_id=:tenant AND status='SCHEDULED' AND scheduled_at<=now() ORDER BY scheduled_at,id LIMIT 50",map("tenant",tenant));});int processed=0;for(var r:due){UUID id=(UUID)r.get("id");try{b.tx.execute(status->{b.context(tenant);var a=b.actor(tenant,(UUID)r.get("launchByMemberId"));long av=b.db.queryForObject("SELECT auth_version FROM iam_user WHERE id=:id",map("id",a.session().userId()),Long.class);if(av!=number(r,"launchAuthVersion")||!a.p3Access().campaignLaunch())throw ApiError.forbidden("排期授权已变化");var k=campaign(a,id);action(a.session(),id,"launch",new Decision(number(k,"version"),null,"自动执行已授权排期"),"scheduled:"+id+":"+k.get("version"),UUID.randomUUID());return null;});processed++;}catch(Exception e){b.tx.executeWithoutResult(st->{b.context(tenant);var p=map("tenant",tenant,"id",id);int changed=b.db.update("UPDATE crm_campaign SET status='BLOCKED',version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND status='SCHEDULED'",p);if(changed>0)b.db.update("INSERT INTO crm_campaign_revision(id,tenant_id,campaign_id,business_version,action,snapshot,reason,actor_member_id,actor_name_snapshot) SELECT gen_random_uuid(),x.tenant_id,x.id,x.version,'BLOCKED',to_jsonb(x),'排期执行前权限、许可或配置复核未通过',x.launch_by_member_id,m.display_name FROM crm_campaign x JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.launch_by_member_id WHERE x.tenant_id=:tenant AND x.id=:id",p);});}}return processed;}
 public byte[] export(AuthService.Session s,UUID id,UUID trace){return b.scoped(s,"export-campaign",false,a->{campaign(a,id);var rs=members(a,id,false);var data=new ArrayList<List<Object>>();for(var r:rs){var sub=(Map<?,?>)r.get("subject");var cons=(Map<?,?>)r.get("consent");data.add(Arrays.asList(sub.get("type"),sub.get("name"),sub.get("company"),cons.get("state"),r.get("version")));}b.audit(a,"CAMPAIGN_TARGETS_EXPORTED","CAMPAIGN",id,number(campaign(a,id),"version"),trace);return CsvSupport.write(List.of("目标类型","联系人","公司","当前渠道许可","目标版本"),data);});}
}
